let known: Set<string> | null = null;

/** Name-key normalization: diacritics folded, lowercased, non-alphanumerics dropped. */
function nameKey(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
}

/** Whether a single word is in the known-first-names dataset. Lazy-parses the blob on first call. */
export function isKnownFirstName(word: string): boolean {
  if (!known) known = new Set(RAW.split(","));
  const key = nameKey(word);
  return key.length >= 2 && known.has(key);
}

/** How many names the dataset holds (for diagnostics/UI). */
export function knownFirstNameCount(): number {
  if (!known) known = new Set(RAW.split(","));
  return known.size;
}
